# Étape 8 — Les prolongations (madd)
from ctx import *
E = 8
MADD = 'ٓ'
PMADD = lambda l, mk: MADD in mk
PSILA = lambda l, mk: l == 'ه' and ('ۥ' in mk or 'ۦ' in mk or True)

def stopw(s, a, i):
    """mot lu à l'arrêt (dernière voyelle remplacée par un soukoun)"""
    w = re.sub('[\u06e2\u06ed]$', '', tokens(s, a)[i - 1])
    return re.sub('[ًٌٍَُِٖٗٞ]$', 'ْ', w)

